        aeq<=epoch;alq<=layer;
        if(aq)begin ke<=aeq;kl<=alq;end
        mt<=vrq?vtq:tq;mv<=vrq|vq;me<=vrq?ke:eq;ml<=vrq?kl:lq;
      end
      always @(posedge ck or negedge rn)if(!rn)aq<=0;else aq<=arm;
      always @(posedge ck or negedge rn)if(!rn)mq<=0;else mq<=rq|vrq;
      assign collide=rq&vrq;
      assign pc_get={4{mq}};assign pc_get_t={4{mt}};assign pc_get_v={4{mv}};
      assign pc_get_epoch={4{me}};assign pc_get_layer={4{ml}};
    end else begin:g_k
      assign collide=1'b0;
      assign pc_get={4{rq}};assign pc_get_t={4{tq}};assign pc_get_v={4{vq}};
      assign pc_get_epoch={4{eq}};assign pc_get_layer={4{lq}};
    end endgenerate
    (* keep *) reg [3:0] iv,ivv,ifault;
    (* keep *) reg [55:0] it;
    (* keep *) reg [63:0] ie;
    (* keep *) reg [23:0] il;
    generate if(DATA!=0)begin:g_data
      (* keep *) reg [1023:0] idata;
      always @(posedge ck)idata<=pc_data;
      assign xdata=idata;
    end else begin:g_nodata
      assign xdata=1024'd0;
    end endgenerate
    always @(posedge ck)begin
      it<=pc_t;ivv<=pc_v;ie<=pc_epoch;il<=pc_layer;
    end
    always @(posedge ck or negedge rn)
      if(!rn)begin iv<=0;ifault<=0;fault<=0;end
      else begin
        iv<=pc_valid;ifault<=pc_fault;
        if((|ifault)||iv!={4{iv[0]}}||collide)fault<=1;
        if(iv[0]&&((it!={4{it[13:0]}})||(ivv!={4{ivv[0]}})||(ie!={4{ie[15:0]}})||(il!={4{il[5:0]}})))fault<=1;
      end
    // KV-GRP5 s4: the old single output register set (rsp_*) is now two KEPT exit copies with the same D and edge,
    // one per E-face pin group (rsp / krsp), so no data flop drives two pins ~196 um apart.  +0 cycles.
    wire [1061:0] xd = {il[5:0], ie[15:0], ivv[0], it[13:0], xdata, iv[0]};
    wire [1061:0] ra, kb;
    qkd_kvs_rsp_exit_s4 u_rsp_x (.ck(ck), .rn(rn), .d((MUT == 10) ? (xd ^ (1062'd1 << 1025)) : xd), .q(ra));
    qkd_kvs_rsp_exit_s4 u_krsp_x (.ck(ck), .rn(rn), .d((MUT == 9) ? (xd ^ 1062'd2) : xd), .q(kb));
    assign {rsp_layer, rsp_epoch, rsp_v, rsp_t, rsp_data, rsp_valid} = ra;
    assign krsp_w = kb;
endmodule

// KV-GRP5: one KEPT exit copy of the row-control response stage (1062 b = krsp order {layer, epoch, v, t, data,
// valid}).  valid is reset (asynchronously, by the row control's landed rn) exactly as the old rsp_valid; the payload
// has no reset, as before.  keep_hierarchy (and the kit's SYNTH_KEEP_MODULES) keeps the two instances separate.
(* keep_hierarchy *)
module qkd_kvs_rsp_exit_s4 (input wire ck, input wire rn, input wire [1061:0] d, output wire [1061:0] q);
    (* keep *) reg v;
    (* keep *) reg [1060:0] p;
    always @(posedge ck or negedge rn) if (!rn) v <= 1'b0; else v <= d[0];
    always @(posedge ck) p <= d[1061:1];
    assign q = {p, v};
endmodule
